class CfAccessException extends RuntimeException {}
function cf_text(mixed $v,int $max=160):string {if(!is_scalar($v)&&$v!==null)throw new DomainException('Invalid text.');$v=trim((string)$v);if(strlen($v)>$max)throw new DomainException('A field is too long.');return $v;}
function cf_date(mixed $v,bool $optional=false):string {$v=cf_text($v,10);if($optional&&$v==='')return ''; $d=DateTimeImmutable::createFromFormat('!Y-m-d',$v);if(!$d||$d->format('Y-m-d')!==$v)throw new DomainException('Enter a valid date.');return $v;}
function cf_number(mixed $v,bool $zero=true):float {if(!is_numeric($v)||!is_finite((float)$v)||(float)$v<0||(float)$v>1e11)throw new DomainException('Enter a valid non-negative amount.');$n=round((float)$v,2);if(!$zero&&$n<=0)throw new DomainException('Amount must be greater than zero.');return $n;}
function cf_rate(mixed $v,bool $zero=false):float {if(!is_numeric($v)||!is_finite((float)$v)||(float)$v<0||(float)$v>1e6||(!$zero&&(float)$v<=0))throw new DomainException('Enter a valid carrying exchange rate.');return round((float)$v,8);}
function cf_currency(mixed $v):string {$v=strtoupper(cf_text($v,3));if(!in_array($v,(array)(tt_master_options()['currencies']??[]),true))throw new DomainException('Choose a currency from Currency Master.');return $v;}
function cf_management(array $u,string $e):bool {return job_authorized($u)&&in_array($e,job_entities($u),true)&&(($u['role']??'')==='Super Admin'||!tt_user_can_open_module($u,'Accounts')||tt_user_can_access_entity($u,$e,'Approve'));}
