function cf_access(array $u,string $e,bool $management=false):void {if(!in_array($e,cf_entities($u),true)||($management&&!cf_management($u,$e)))throw new CfAccessException('You do not have permission for these company books.');}
function cf_bill_permission(array $u,string $e,string $kind):bool {$icon=$e==='TG'?'supplier':match($kind){'FREIGHT'=>'freight','TRANSPORT'=>'transport','CLEARING','FUMIGATION','INSPECTION'=>'services','BAGS'=>'purchases',default=>'expenses'};return tt_user_can_open_module($u,'Accounts')&&tt_user_can_access_entity($u,$e,'Create')&&(tt_user_can_module_action($u,'Accounts',$icon,'Create')||tt_user_can_module_action($u,'Accounts',$icon,'Approve'));}
function cf_catalog():array {$m=json_decode((string)file_get_contents(__DIR__.'/../accounts/accounting_master_v1.json'),true,512,JSON_THROW_ON_ERROR);$out=[];foreach($m['chart'] as $a)$out[(string)$a['code']]=$a['name'];return $out;}
function cf_party(string $id):array {foreach((array)(tt_list_masters()['business_parties']??[]) as $p)if((string)($p['id']??'')===$id&&strcasecmp((string)($p['values'][10]??'Active'),'Inactive')!==0)return $p;throw new DomainException('Choose an active Business Party.');}
function cf_customer(string $id):string {foreach((array)(tt_list_masters()['export_customers']??[]) as $p)if((string)($p['id']??'')===$id&&strcasecmp((string)($p['values'][10]??'Active'),'Inactive')!==0)return cf_text($p['values'][0]);throw new DomainException('Choose an Export Customer from Master Records.');}
function cf_bill_map(string $kind):array {return match($kind){'FREIGHT'=>['5520','2130',['Freight Forwarder','Shipping Line / Carrier']],'TRANSPORT'=>['5510','2130',['Transporter']],'CLEARING'=>['5530','2130',['Clearing Agent']],'FUMIGATION'=>['5540','2130',['Fumigation']],'INSPECTION'=>['5530','2130',['Inspection']],'BAGS'=>['5550','2140',['Bag Supplier']],'OTHER'=>['5550','2140',['Service Provider','Other','Agent']],default=>throw new DomainException('Rice is paid through Bank Payment. Choose a shipment expense category.')};}
