 $invoice=cf_text($b['invoiceNo']??'');if($invoice==='')throw new DomainException('Bill invoice/reference is required.');$amount=cf_number($b['amount']??0,false);$paid=cf_number($b['paidBefore']??0);if($paid>$amount)throw new DomainException('Already paid exceeds the bill amount.');$date=cf_date($b['billDate']??'');$treatment=cf_text($b['treatment']??'CURRENT');if(!in_array($treatment,['CURRENT','NEW','LINK','PAID'],true))throw new DomainException('Choose the bill accounting position.');if($treatment==='CURRENT'&&($date<CF_CUTOFF||$paid>0))throw new DomainException('A new current-year bill needs a date from 1 July and no already-paid amount. Link an existing posting for bills already recorded.');if(in_array($treatment,['NEW','LINK'],true)&&$date>=CF_CUTOFF)throw new DomainException('Opening payable bills must be dated before 1 July.');if($treatment==='PAID'&&abs($amount-$paid)>.005)throw new DomainException('A paid bill must have zero balance.');
