function cf_clean(array $b,array $s,array $u):array {
 $e=strtoupper(cf_text($b['entity']??'',3));if(!in_array($e,['TTI','BRM'],true))throw new DomainException('Select the Pakistan exporter TTI or BRM.');cf_access($u,$e,true);$tg=($b['tgPack']??false)===true;if($tg)cf_access($u,'TG',true);
 $date=cf_date($b['shipmentDate']??'');if($date>CF_LAST_SHIPMENT_DATE)throw new DomainException('Invoice and B/L dates must be on or before 1 October 2026.');
