 foreach(['contractRef','lotRef','blNo','loadingProgrammeNo','shippingLine','forwarder','vessel','voyage','portOfLoading','portOfDischarge','goods','brand','bagPoNo'] as $key)$r[$key]=cf_text($b[$key]??'');if($r['contractRef']===''||$r['lotRef']===''||$r['blNo']==='')throw new DomainException('Shipment/contract, lot and B/L references are required.');
 $r['quantityMT']=cf_number($b['quantityMT']??0);$r['containerCount']=(int)($b['containerCount']??0);if($r['containerCount']<0||$r['containerCount']>10000)throw new DomainException('Invalid container count.');$r['containers']=array_values(array_unique(array_filter(array_map(static fn($v)=>cf_text($v,25),(array)($b['containers']??[])))));if(count($r['containers'])>$r['containerCount'])throw new DomainException('Container numbers exceed the stated container count.');
 $r['buyerBalance']=cf_balance((array)($b['buyerBalance']??[]));if($r['buyerBalance']['invoiceNo']===''||$r['buyerBalance']['invoiceAmount']<=0)throw new DomainException('Enter the buyer invoice number and value.');
 if($tg){$r['pakistanBalance']=cf_balance((array)($b['pakistanBalance']??[]));$r['tgPayableBalance']=cf_balance((array)($b['tgPayableBalance']??[]));$p=$r['pakistanBalance'];$t=$r['tgPayableBalance'];if($p['invoiceNo']===''||$p['invoiceAmount']<=0||$p['invoiceNo']!==$t['invoiceNo']||$p['currency']!==$t['currency']||abs($p['invoiceAmount']-$t['invoiceAmount'])>.005||abs($p['receivedBefore']-$t['receivedBefore'])>.005)throw new DomainException('Pakistan → TG invoice, currency, value and pre-July settlements must agree on both sides.');}
