  $lcur=(string)($line['nativeCurrency']??$line['currency']??$base);$capacity=cf_number($line[$side==='Debit'?'nativeDebit':'nativeCredit']??($cur===$base?($line[strtolower($side)]??0):0));$book=cf_number($line[strtolower($side)]??0);if($lcur!==$cur||$capacity<=0)throw new DomainException('Currency must match the existing opening line.');$rate=$book/$capacity;$amount=round($native*$rate,2);
  $used=0;foreach((array)($s['carryForwardOpeningLinks']??[]) as $link)if($link['journalId']===$jid&&$link['lineIndex']===$index)$used+=(float)$link['nativeAmount'];if($used+$native>$capacity+.005)throw new DomainException('This opening line does not have enough unassigned balance.');
 }else{
