 }
 $s['carryForwardOpeningLinks'][$key]=['shipmentId'=>$record,'journalId'=>$jid,'lineIndex'=>$index,'nativeAmount'=>$native,'currency'=>$cur,'entity'=>$e];return ['journalId'=>$jid,'amount'=>$amount,'rate'=>$rate];
